Send SMS.code:
// Send an SMS via Vonage / Nexmo.
sendSMS(
  // 1) Sender id (alphanumeric or your Vonage number, E.164).
  $.configuration.fromNumber,
  // 2) Recipient, E.164 format.
  $.data.phone,
  // 3) Message body.
  `Hi ${$.data.name}, your appointment is confirmed.`
);

Make Call.code:
// Place a voice call.
// Limitation: the nexmo adaptor only supports SMS (sendSMS); Vonage voice calls need the
// Voice API with application (JWT) auth, which this credential doesn't provide.
// Closest working option: send the message as an SMS instead.
sendSMS(
  // 1) Sender id (alphanumeric or your Vonage number, E.164).
  $.configuration.fromNumber,
  // 2) Recipient, E.164 format.
  $.data.phone,
  // 3) Message body.
  `Hi ${$.data.name}, please call the clinic on ${$.configuration.fromNumber} about your results.`
);
